  "It asks to:": "Es möchte:",
  "It closed before it opened. Try again.": "Es hat sich geschlossen, bevor es richtig offen war. Versuch es noch mal.",
  "It couldn’t start on this Mac.": "Es konnte auf diesem Mac nicht starten.",
  "It ended before it could write up the build.": "Es endete, bevor es den Build zusammenfassen konnte.",
  "It finishes its own setup the first time it opens.": "Beim ersten Öffnen schließt es seine Einrichtung selbst ab.",
  "It hasn't started yet.": "Es hat noch nicht angefangen.",
  "It installs when you relaunch; Genex tells you when it's ready.":
    "Sie wird beim Neustart installiert; Genex sagt dir Bescheid, wenn sie bereit ist.",
  "It is on and stays on: its new code runs as soon as it loads, and each of its tools asks you again before it runs.":
    "Es ist an und bleibt an: Sein neuer Code läuft, sobald er geladen ist, und jedes seiner Tools fragt dich erneut, bevor es läuft.",
  "It isn’t on this Mac any more. Install it again.": "Es ist nicht mehr auf diesem Mac. Installier es neu.",
  "It keeps downloading if you go back.": "Der Download läuft weiter, wenn du zurückgehst.",
  "It keeps your scripts as files in this game's folder and tells Genex which Studio is this game's.":
    "Es speichert deine Skripte als Dateien im Ordner dieses Spiels und sagt Genex, welches Studio zu diesem Spiel gehört.",
  "It kept getting this wrong, so it stopped to save your credits.":
    "Das ging immer wieder schief, also wurde gestoppt, um deine Credits zu sparen.",
  "It leaves Play and genex.games and goes back to drafts. The direct link still works, and plays and likes stay if it’s published again.":
    "Es verschwindet aus „Spielen“ und von genex.games und kommt zurück zu den Entwürfen. Der direkte Link funktioniert weiter, und Spielzahlen und Likes bleiben, wenn du es wieder veröffentlichst.",
  "It leaves the game’s Store. Players who own it keep it.":
    "Es verschwindet aus dem Shop des Spiels. Wer es hat, behält es.",
  "It may need the setup scripts its packages came with, which didn’t run.":
    "Es braucht vielleicht die Setup-Skripte seiner Pakete, die nicht gelaufen sind.",
  "It merged this part's work without a reviewer's verdict. The reviewers score parts that build in steps; this one was built in one session.":
    "Er hat die Arbeit dieses Teils ohne Urteil eines Prüfers übernommen. Die Prüfer bewerten Teile, die in Schritten entstehen; dieser wurde in einer einzigen Sitzung gebaut.",
  "It merges into your build when the lead integrates this part.":
    "Es kommt in deinen Build, wenn der Hauptagent diesen Teil einbaut.",
  "It needs macOS {version} or later.": "Es braucht macOS {version} oder neuer.",
  "It never uses password managers, Windows Settings, password prompts or Genex.":
    "Passwortmanager, die Windows-Einstellungen, Passwortabfragen und Genex nutzt es nie.",
  "It ran into an error": "Es gab einen Fehler",
  "It runs at Genex's moments: {steps}; those steps don't ask you first.":
    "Es läuft an festen Stellen in Genex: {steps}; diese Schritte fragen dich vorher nicht.",
  "It runs with your access: Genex doesn't sandbox its code.":
    "Es läuft mit deinen Rechten: Genex isoliert seinen Code nicht.",
  "It runs, but no reviewer compared it with the game you had.":
    "Es läuft, aber kein Prüfer hat es mit deinem bisherigen Spiel verglichen.",
  "It shows in the game after its next release.": "Es erscheint im Spiel nach seinem nächsten Release.",
  "It shows up here as soon as it runs.": "Es erscheint hier, sobald es läuft.",
  "It starts off: turn it on in Plugins; each of its tools asks you before it runs.":
    "Es startet ausgeschaltet: Schalte es unter „Plugins“ ein; jedes seiner Tools fragt dich, bevor es läuft.",
  "It stopped before this was fixed.": "Es wurde gestoppt, bevor das behoben war.",
  "It treats this as a {kind} game — that decides the controls it drives before every look, and who reviews it.":
    "Es behandelt das als „{kind}“-Spiel – das bestimmt, welche Steuerung es vor jedem Blick bedient und wer es prüft.",
  "It turns on when installed: agents in all your games can use it from your next message.":
    "Es ist nach der Installation aktiv: Agenten in all deinen Spielen können es ab deiner nächsten Nachricht nutzen.",
  "It was paused before it could write up the build.": "Es wurde pausiert, bevor es den Build zusammenfassen konnte.",
  "It's no longer there.": "Es ist nicht mehr da.",
  "It's switched on in Studio's settings. Studio answers once a place is open: open one in Studio, or press New Roblox game.":
    "Er ist in den Einstellungen von Studio eingeschaltet. Studio antwortet, sobald ein Ort offen ist: Öffne einen in Studio oder drücke „Neues Roblox-Spiel“.",
  "It's switched on in Studio's settings. Studio answers once it has finished opening.":
    "Er ist in den Einstellungen von Studio eingeschaltet. Studio antwortet, sobald es fertig geöffnet ist.",
  "Its author no longer shares it.": "Der Autor teilt es nicht mehr.",
  "Its code runs on your computer like an app you install. It isn't sandboxed.":
    "Sein Code läuft auf deinem Computer wie eine installierte App. Es läuft nicht in einer Sandbox.",
  "Its creator hasn’t shared this game’s project yet, so it can’t be remixed.":
    "Der Macher hat das Projekt dieses Spiels noch nicht geteilt, deshalb kann man es nicht remixen.",
  "Its files are in your game folder, waiting for the lead to use them.":
    "Die Dateien liegen in deinem Spielordner und warten darauf, dass der Hauptagent sie nutzt.",
  "Its own scene": "Eigene Szene",
  "Its packages aren’t installed yet — “{install}” runs on one press.":
    "Die Pakete sind noch nicht installiert – „{install}“ läuft mit einem Klick.",
  "Its packages aren’t installed yet.": "Die Pakete sind noch nicht installiert.",
  "Its project didn’t go, so no one can remix it yet.":
    "Das Projekt wurde nicht gesendet, deshalb kann es noch niemand remixen.",
  "Its project is too big to remix: Genex keeps up to 5 GB and 5,000 files.":
    "Das Projekt ist zu groß zum Remixen: Genex speichert bis zu 5 GB und 5.000 Dateien.",
  "Its session failed before it delivered anything.": "Die Sitzung ist fehlgeschlagen, bevor etwas geliefert wurde.",
  "Its source is your own repository: run genex make-remixable in the game’s folder to allow remixing.":
    "Der Quellcode liegt in deinem eigenen Repository: Führe genex make-remixable im Ordner des Spiels aus, um Remixe zu erlauben.",
  "Its steps at Genex's moments changed (hooks, observers, locks, folders or harness tools), so it wasn't reloaded: load it again with Load local plugin… to review them":
    "Seine Schritte an festen Stellen in Genex haben sich geändert (Hooks, Beobachter, Sperren, Ordner oder Harness-Tools), daher wurde es nicht neu geladen: Lade es mit „Lokales Plugin laden…“ erneut, um sie zu prüfen",
