  "Roblox Studio closed. It asked to save anything unsaved first.":
    "Roblox Studio wurde geschlossen. Vorher hat es gefragt, ob Ungespeichertes gespeichert werden soll.",
  "Roblox Studio didn't say what {name} is. If a play test or a dialog is open in Studio, finish it, then choose the place again.":
    "Roblox Studio hat nicht gesagt, was {name} ist. Falls in Studio ein Spieltest oder ein Dialog offen ist, beende ihn und wähle den Ort noch mal.",
  "Roblox Studio is already on this computer.": "Roblox Studio ist schon auf diesem Computer.",
  "Roblox Studio is already open.": "Roblox Studio ist schon offen.",
  "Roblox Studio is installed and set up.": "Roblox Studio ist installiert und eingerichtet.",
  "Roblox Studio is on this computer": "Roblox Studio ist auf diesem Computer",
  "Roblox Studio is open and answering Genex.": "Roblox Studio ist offen und antwortet Genex.",
  "Roblox Studio is open, and Genex adds its helper only while Studio is closed. Restart Studio closes it, sets it up and opens it again.":
    "Roblox Studio ist offen, und Genex fügt sein Plugin nur hinzu, solange Studio geschlossen ist. „Studio neu starten“ schließt es, richtet es ein und öffnet es wieder.",
  "Roblox Studio is open. Genex changes Studio's settings only while it is closed: press Restart Studio, or turn the switch on yourself in Studio.":
    "Roblox Studio ist offen. Genex ändert die Einstellungen von Studio nur, solange es geschlossen ist: Drücke „Studio neu starten“ oder schalte den Schalter selbst in Studio ein.",
  "Roblox Studio is open. Genex is waiting for it to answer.":
    "Roblox Studio ist offen. Genex wartet auf eine Antwort.",
  "Roblox Studio is opening again with the Genex helper.": "Roblox Studio öffnet sich mit dem Genex-Plugin neu.",
  "Roblox Studio is set up but not open.": "Roblox Studio ist eingerichtet, aber nicht geöffnet.",
  "Roblox Studio is still open. If it asked to save your place, answer it, then press Quit Studio again.":
    "Roblox Studio ist noch offen. Falls es gefragt hat, ob dein Ort gespeichert werden soll, antworte und drücke dann noch mal „Studio beenden“.",
  "Roblox Studio is still open. If it asked to save your place, answer it, then press Restart Studio again.":
    "Roblox Studio ist noch offen. Falls es gefragt hat, ob dein Ort gespeichert werden soll, antworte und drücke dann noch mal „Studio neu starten“.",
  "Roblox Studio is still open, and nobody signed in to Roblox there in time. Sign in there, then press Set it up for me so Genex can finish.":
    "Roblox Studio ist noch offen, und niemand hat sich dort rechtzeitig bei Roblox angemeldet. Melde dich dort an und drücke dann „Richte es für mich ein“, damit Genex fertig werden kann.",
  "Roblox Studio isn't on this computer.": "Roblox Studio ist nicht auf diesem Computer.",
  "Roblox Studio isn't on this computer. Open this to get it.":
    "Roblox Studio ist nicht auf diesem Computer. Öffne das hier, um es zu holen.",
  "Roblox Studio isn't on this computer. Press Get Roblox Studio first.":
    "Roblox Studio ist nicht auf diesem Computer. Drücke zuerst „Roblox Studio holen“.",
  "Roblox Studio isn't open.": "Roblox Studio ist nicht offen.",
  "Roblox Studio runs on a Mac or on Windows only.": "Roblox Studio läuft nur auf dem Mac oder unter Windows.",
  "Roblox Studio setup": "Roblox Studio einrichten",
  "Roblox Studio {version} is already on this computer.": "Roblox Studio {version} ist schon auf diesem Computer.",
  "Roblox Studio {version} is on this computer": "Roblox Studio {version} ist auf diesem Computer",
  "Roblox Studio {version} is set up but not open.": "Roblox Studio {version} ist eingerichtet, aber nicht geöffnet.",
  "Roblox's download didn't hold its installer, so Genex didn't run anything.":
    "Der Download von Roblox enthielt kein Installationsprogramm, deshalb hat Genex nichts gestartet.",
  "Roblox's installer finished, but Roblox Studio didn't appear. Press Get Roblox Studio to try again.":
    "Das Installationsprogramm von Roblox ist fertig, aber Roblox Studio ist nicht aufgetaucht. Drücke „Roblox Studio holen“, um es noch mal zu versuchen.",
  "Roblox's installer is installing Studio.": "Das Installationsprogramm von Roblox installiert Studio.",
  "Roblox's installer stopped before it finished. Press Get Roblox Studio to try again.":
    "Das Installationsprogramm von Roblox hat vor dem Ende aufgehört. Drücke „Roblox Studio holen“, um es noch mal zu versuchen.",
