  "Studio starts this program on your Mac as trusted native code with the environment variables you named. A separate process is crash isolation, not a security sandbox.\nProgram: {program}\nArguments: {args}\nWorking directory: {folder}\nEnvironment variables: {variables}":
    "Studio startet dieses Programm auf deinem Mac als vertrauenswürdigen nativen Code mit den Umgebungsvariablen, die du angegeben hast. Ein eigener Prozess fängt Abstürze ab, ist aber keine Sicherheits-Sandbox.\nProgramm: {program}\nArgumente: {args}\nArbeitsordner: {folder}\nUmgebungsvariablen: {variables}",
  "Studio still couldn’t start:": "Studio konnte immer noch nicht starten:",
