  "The folder this plugin was loaded from is gone; load it again":
    "Der Ordner, aus dem dieses Plugin geladen wurde, ist weg; lade es erneut",
  "The game changed — reload to see it": "Das Spiel hat sich geändert – neu laden, um es zu sehen",
  "The game didn’t build": "Der Build ist fehlgeschlagen",
  "The game files changed through a commit or a landed build since this message, so they stay as they are.":
    "Die Spieldateien haben sich seit dieser Nachricht durch einen Commit oder einen übernommenen Build geändert, deshalb bleiben sie, wie sie sind.",
  "The game files could not be saved before rewinding.":
    "Die Spieldateien konnten vor dem Zurückspulen nicht gespeichert werden.",
  "The game files haven’t changed since this message.":
    "Die Spieldateien haben sich seit dieser Nachricht nicht geändert.",
  "The game gets a new folder of its own inside the folder you choose.":
    "Das Spiel bekommt in dem gewählten Ordner einen eigenen neuen Ordner.",
  "The game is back as it was before the rewind. The chat stays rewound.":
    "Das Spiel ist wieder wie vor dem Zurückspulen. Der Chat bleibt zurückgespult.",
  "The game stays as it is. You can run them later from here.":
    "Das Spiel bleibt, wie es ist. Du kannst sie später hier ausführen.",
