    "In {place} gibt es schon etwas namens {name}. Wähl einen anderen Namen.",
  "There's no Unreal project file at that path.": "Unter diesem Pfad gibt es keine Unreal-Projektdatei.",
  "There's no place file at {file}.": "Unter {file} gibt es keine Ortsdatei.",
  "There’s no plugin here: this repository has no plugin.json.":
    "Hier ist kein Plugin: Dieses Repository hat keine plugin.json.",
