  "There’s no {platform} version of this game yet.": "Es gibt noch keine {platform}-Version dieses Spiels.",
  Thermal: "Wärmebild",
  "These aren't Roblox Studio's settings: Studio keeps one JSON object.":
    "Das sind nicht die Einstellungen von Roblox Studio: Studio speichert ein einziges JSON-Objekt.",
  "These files were too large to save, so the rewind left them as they are: {files}.":
    "Diese Dateien waren zu groß zum Speichern, deshalb hat das Zurückspulen sie so gelassen, wie sie sind: {files}.",
  "These surfaces need different text colors. Use similar background brightness, or reset this theme.":
    "Diese Flächen brauchen unterschiedliche Textfarben. Nutze Hintergründe mit ähnlicher Helligkeit oder setz dieses Design zurück.",
  "They can": "Sie dürfen",
  "They get the Genex download page with a card from you.":
    "Sie bekommen die Genex-Downloadseite mit einer Karte von dir.",
  "They get the Genex download page with a card from you. You get {count} credits when they make their first game.":
    "Sie bekommen die Genex-Downloadseite mit einer Karte von dir. Du bekommst {count} Credits, wenn sie ihr erstes Spiel machen.",
  "They preferred the build before it.": "Sie fanden den Build davor besser.",
  "They preferred this build to the one before it.": "Sie fanden diesen Build besser als den davor.",
  "They run in Genex’s sandbox and can’t change your other games.":
    "Sie laufen in der Sandbox von Genex und können deine anderen Spiele nicht ändern.",
  "They’re in {folder}. Connect that drive, then try again.":
    "Sie liegen in {folder}. Schließ dieses Laufwerk an und versuch es noch mal.",
  Thinking: "Denkt nach",
  "Thinking details": "Gedankengang",
  "This .uproject file isn't valid JSON, so Genex won't change it.":
    "Diese .uproject-Datei ist kein gültiges JSON, deshalb ändert Genex sie nicht.",
  "This Godot isn't signed by the Godot team, so Genex didn't install it.":
    "Dieses Godot ist nicht vom Godot-Team signiert, deshalb hat Genex es nicht installiert.",
  "This Loop": "Dieser Loop",
  "This Mac can't draw live backgrounds.": "Dieser Mac kann keine Live-Hintergründe darstellen.",
  "This Unity Hub isn't signed by Unity, so Genex didn't install it.":
    "Dieser Unity Hub ist nicht von Unity signiert, deshalb hat Genex ihn nicht installiert.",
  "This Unreal template can't be used: it brings C++ code.":
    "Diese Unreal-Vorlage ist nicht nutzbar: Sie bringt C++-Code mit.",
  "This Unreal template can't be used: it has no Config/TemplateDefs.ini.":
    "Diese Unreal-Vorlage ist nicht nutzbar: Sie hat keine Config/TemplateDefs.ini.",
  "This Unreal template can't be used: it needs its own C++ setup code.":
    "Diese Unreal-Vorlage ist nicht nutzbar: Sie braucht eigenen C++-Setup-Code.",
  "This Unreal template can't be used: its .uproject is missing.":
    "Diese Unreal-Vorlage ist nicht nutzbar: Ihre .uproject-Datei fehlt.",
  "This Unreal template can't be used: its shared pack {pack} is missing.":
    "Diese Unreal-Vorlage ist nicht nutzbar: Ihr gemeinsames Paket {pack} fehlt.",
  "This Unreal template can't be used: its shared pack {pack} names files outside the engine.":
    "Diese Unreal-Vorlage ist nicht nutzbar: Ihr gemeinsames Paket {pack} nennt Dateien außerhalb der Engine.",
  "This account is signed out": "Dieses Konto ist abgemeldet",
  "This audio codec could not be played. Try a WAV, MP3 or Ogg export.":
    "Dieser Audio-Codec kann nicht abgespielt werden. Versuch einen Export als WAV, MP3 oder Ogg.",
  "This build": "Dieser Build",
  "This build doesn't check for updates.": "Dieser Build sucht nicht nach Updates.",
  "This build is your game now": "Dieser Build ist jetzt dein Spiel",
  "This build is your game now — open Live to play it.":
    "Dieser Build ist jetzt dein Spiel – öffne „Live“, um es zu spielen.",
  "This build of Genex doesn't check for updates.": "Dieser Build von Genex sucht nicht nach Updates.",
  "This build of Genex doesn’t include its license files.": "Dieser Genex-Build enthält keine Lizenzdateien.",
  "This build of Genex has build metrics sharing removed.":
    "In diesem Genex-Build wurde das Teilen von Build-Metriken entfernt.",
  "This build of the studio can't pick a build back up yet — its own loop code predates timed builds.":
    "Diese Version von Studio kann einen Build noch nicht fortsetzen – ihr Loop-Code ist älter als zeitgesteuerte Builds.",
  "This build of the studio can't run a timed build yet — your brief is saved above, and sending it again once the studio has updated itself will start the build. (Its own loop code predates timed builds: the seed's harness-seed/loop needs to be merged into it, or the seed copies restored so the next launch upgrades them.)":
    "Diese Version von Studio kann noch keinen zeitgesteuerten Build ausführen – dein Auftrag ist oben gespeichert. Schick ihn erneut, sobald Studio sich aktualisiert hat, dann startet der Build. (Ihr Loop-Code ist älter als zeitgesteuerte Builds: Das harness-seed/loop der Basis muss in ihn übernommen werden, oder die Basis-Kopien werden wiederhergestellt, damit der nächste Start sie aktualisiert.)",
  "This build turned out not to run — reload to go back to your game":
    "Dieser Build läuft nicht – neu laden, um zu deinem Spiel zurückzukehren",
  "This build's workers or reviewers run on a local model, which the studio's own loop code doesn't support yet — your brief is saved above. Pick every job on one kind of engine and send it again, or ask the studio to merge the seed's harness-seed/loop into its own loop code (or restore the seed copies) so the next launch upgrades them.":
    "Helfer oder Prüfer dieses Builds laufen auf einem lokalen Modell, das der Loop-Code von Studio noch nicht unterstützt – dein Auftrag ist oben gespeichert. Wähle für alle Aufgaben dieselbe Art von Engine und schick ihn erneut, oder bitte Studio, das harness-seed/loop der Basis in seinen Loop-Code zu übernehmen (oder die Basis-Kopien wiederherzustellen), damit der nächste Start sie aktualisiert.",
  "This change no longer differs from what Harness has now.":
    "Diese Änderung unterscheidet sich nicht mehr von dem, was Harness jetzt hat.",
  "This change was already undone.": "Diese Änderung wurde schon rückgängig gemacht.",
